enum _nslSourceTypeEnum { NSL_SOURCETYPE_SFX = 0, NSL_SOURCETYPE_AMBIENT = 1, NSL_SOURCETYPE_MUSIC = 2, NSL_SOURCETYPE_VOICE = 3 };
typedef int nslSpeakerModeEnum;
float nslGetMasterVolume();
float nslGetVolume(_nslSourceTypeEnum);
nslSpeakerModeEnum nslGetSpeakerMode();
class os_developer_options { public: enum flags_t { FLAG_NO_AUDIO = 18 }; int padding[18]; int flags; static os_developer_options *instance; static os_developer_options *inst() { return instance; } bool is_flagged(flags_t flag) { return flags & (1 << flag); } };
__asm__(".equ _20os_developer_options$instance, 0x0045B180");
const int MAX_SONGS = 50;
struct MusicTrack { char padding[0xe30]; int order[MAX_SONGS]; bool enabled[MAX_SONGS]; };
class MusicMan { public: MusicTrack musicTrack; static MusicMan *instance; static MusicMan *inst() { return instance; } };
__asm__(".equ _8MusicMan$instance, 0x00427B18");
class rumbleManager { public: bool isOn(int); };
extern rumbleManager rumbleMan;
__asm__(".equ rumbleMan, 0x004253C0");
struct FrontEndManager { char padding[0x15660]; bool score_display; };
extern FrontEndManager frontendmanager;
__asm__(".equ frontendmanager, 0x003E7728");
typedef struct { float masterVolume, ambientVolume, musicVolume, voiceVolume, sfxVolume; bool rumbleOn[2]; bool scoreDisplay; nslSpeakerModeEnum audioMode; char camera[2][20]; int order[MAX_SONGS]; bool enabled[MAX_SONGS]; } ksConfigData;
class StoredConfigData { char singleton_base[4]; ksConfigData cData; public: void *getGameConfig(); };

void *StoredConfigData::getGameConfig()
{
  if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
  {

    cData.masterVolume = nslGetMasterVolume();
    cData.ambientVolume = nslGetVolume(NSL_SOURCETYPE_AMBIENT);
    cData.sfxVolume = nslGetVolume(NSL_SOURCETYPE_SFX);
    cData.musicVolume = nslGetVolume(NSL_SOURCETYPE_MUSIC);
    cData.voiceVolume = nslGetVolume(NSL_SOURCETYPE_VOICE);
    cData.audioMode =  nslGetSpeakerMode();
    memcpy(&cData.enabled, &MusicMan::inst()->musicTrack.enabled, sizeof(bool)*MAX_SONGS);
    memcpy(&cData.order, &MusicMan::inst()->musicTrack.order, sizeof(int)*MAX_SONGS);
  }
  cData.rumbleOn[0] = rumbleMan.isOn(0);
  cData.rumbleOn[1] = rumbleMan.isOn(1);
	cData.scoreDisplay = frontendmanager.score_display;
  // We don't get the camera since it should already be set
  return &cData;
}
